async function checkCameraPermissions() {
    try {
        // Solicitar permiso para acceder a la cámara
        const stream = await navigator.mediaDevices.getUserMedia({ video: true });

        // Si se obtiene el stream, significa que el usuario ha concedido el permiso
        console.log("Permiso de cámara concedido. Stream obtenido: ", stream);

        // Cerrar el stream después de usarlo para liberar recursos
        stream.getTracks().forEach(track => track.stop());

    } catch (error) {
        console.error("Error al solicitar permiso de cámara:", error);

        // Comprobar si el error es debido a que el usuario denegó el permiso
        if (error.name === 'NotAllowedError') {
            console.log("Permiso de cámara denegado por el usuario.");
        } else {
            console.error("Otro error:", error);
        }
    }
}

